<span class="line"><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> early </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> astro</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">bySolar</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">1996-8-14</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">female</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
